// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint104 amount1, uint104 amount2, address actor) public {
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(actor != address(0));
        vm.deal(actor, uint256(amount1) + uint256(amount2));
        vm.startPrank(actor);
        c.addToBalance{value: uint256(amount1)}();
        c.addToBalance{value: uint256(amount2)}();
        vm.stopPrank();
        assertTrue(c.getBalance(actor) == uint256(amount1) + uint256(amount2));
    }
}
